script:
// load SheetJS từ CDN
frappe.require("https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js");

frappe.ui.form.on("Furniture Summary", {
    refresh: function(frm) {
        let grid_field = frm.fields_dict["group"];   // fieldname đúng là "group"
        if (!grid_field) return;

        let grid = grid_field.grid;

        if (!grid.download_btn) {
            grid.download_btn = $('<button class="btn btn-sm btn-primary" style="margin-top:10px;">Download Excel</button>');

            grid.download_btn.click(function() {
                // header có thêm Depth
                let rows = [["Item Code", "UOM", "Depth", "Qty", "Rate", "Amount"]];

                (frm.doc.group || []).forEach(d => {
                    rows.push([
                        d.item_code || "",
                        d.uom || "",
                        d.depth || "",   // 👈 thêm trường depth
                        d.total_qty != null ? d.total_qty : "",
                        d.rate != null ? d.rate : "",
                        d.amount != null ? d.amount : ""
                    ]);
                });

                // tạo file Excel
                let wb = XLSX.utils.book_new();
                let ws = XLSX.utils.aoa_to_sheet(rows);
                XLSX.utils.book_append_sheet(wb, ws, "Furniture Group Items");

                XLSX.writeFile(wb, (frm.doc.name || "furniture") + "_furniture_items.xlsx");
            });

            $(grid.wrapper).append(grid.download_btn);
        }
    }
});
